import{c as e,Q as t,j as o,m as n}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"封神演义","description":"","frontmatter":{"id":"fengshenyanyi","title":"封神演义","author":"许仲琳","dynasty":"明代","cover":"/covers/fengshenyanyi.jpg","sort":1,"literaryValue":"《封神演义》是明代许仲琳创作的长篇神魔小说，以商周交替时期的历史为背景，描写了姜子牙辅佐周武王伐纣的故事，充满了神话色彩和想象力。"},"headers":[],"relativePath":"books/shenmo/fengshenyanyi.md","filePath":"books/shenmo/fengshenyanyi.md"}'),r={name:"books/shenmo/fengshenyanyi.md"};function p(s,a,i,h,l,d){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="封神演义" tabindex="-1">封神演义 <a class="header-anchor" href="#封神演义" aria-label="Permalink to &quot;封神演义&quot;">​</a></h1><h2 id="作品简介" tabindex="-1">作品简介 <a class="header-anchor" href="#作品简介" aria-label="Permalink to &quot;作品简介&quot;">​</a></h2><p>《封神演义》（俗称《封神榜》，又名《商周列国全传》《武王伐纣外史》《封神传》等），据传是明代许仲琳创作的长篇小说，约成书于隆庆、万历年间。</p><p>《封神演义》全书一百回，写武王伐纣的故事。前三十回着重写纣王的暴虐，姜子牙归隐，文王访贤，得姜子牙之辅佐，武王才完成讨伐纣王的大业。后七十回主要写商、周两国的战争，并且掺杂有宗教的斗争，阐教帮助周，截教帮助商，各显道术，互有杀伤，结果截教失败，纣王凶而自焚，武王夺取天下，分封列国，姜子牙回国封神，使有功于国的人和鬼各有所归。</p><p>该小说，以历史观念、政治观念作为支撑全书的思想框架，掺杂了很多宏大的想象，表现了作者对于仁君贤主的拥护和赞颂以及对于无道昏君的不满和反抗。</p><h2 id="作者介绍" tabindex="-1">作者介绍 <a class="header-anchor" href="#作者介绍" aria-label="Permalink to &quot;作者介绍&quot;">​</a></h2><p><strong>许仲琳</strong>（约1560年—约1630年），亦作陈仲琳，号钟山逸叟，应天府（今江苏南京市）人，明代小说家。生平事迹不详。</p><h2 id="文学价值" tabindex="-1">文学价值 <a class="header-anchor" href="#文学价值" aria-label="Permalink to &quot;文学价值&quot;">​</a></h2><p>《封神演义》是中国古典小说中历史与神怪题材相结合的完美典范。作者运用丰富的想象力，将商周交替时期的历史事件与神话传说相结合，创造出一个充满奇幻色彩的世界。小说中塑造的姜子牙、哪吒、杨戬等人物形象深入人心，成为中国文化中的经典角色。</p><h2 id="第一回-纣王女娲宫进香" tabindex="-1">第一回 纣王女娲宫进香 <a class="header-anchor" href="#第一回-纣王女娲宫进香" aria-label="Permalink to &quot;第一回 纣王女娲宫进香&quot;">​</a></h2><p>混沌初分盘古先，太极两仪四象悬。 子天丑地人寅出，避除兽患有巢贤。</p><p>燧人取火免鲜食，伏羲画卦阴阳前。 神农治世尝百草，轩辕礼乐婚姻联。</p><p>少昊五帝民物阜，禹王治水洪波蠲。 承平享国至四百，桀王无道乾坤颠。</p><p>日纵妺喜荒酒色，成汤造毫洗腥膻。 放桀南巢拯暴虐，云霓如愿後苏全。</p><p>叁十一世传殷纣，商家脉络如断弦： 紊乱朝纲绝伦纪，杀妻诛子信谗言。</p><p>秽污宫闱宠妲己，虿盆炮烙任冤牵。 鹿台高插云霄上，周氏君臣莫谢天。</p><p>日月潜辉贤人去，关河暗淡怪星连。 有心安社稷，无计保华夷。</p><p>朝生霜露草，暮死秋虫蝉。 不如学隐遁，丘园了残年。</p><p>自混沌初分，天地开辟，然后有君臣、父子、兄弟、夫妇、朋友之伦，相沿至今。自三皇以降，五帝而还，有夏、商、周之代，历代圣君治世，桀、纣之君失德。此皆上古之事，难以尽述。单表成汤乃黄帝之後也，姓子氏，初名帝喾，都于毫。自契至汤，凡十四世。汤伐桀而王天下，国号曰商，六百二十九年。後传至纣王，乃商之末世也。</p><p>纣王乃帝乙之第三子也。帝乙生三子：长曰微子启，次曰微子衍，三曰寿王。这寿王就是纣王。帝乙在位三十年而崩，托孤与太师闻仲，随立寿王为天子，名曰纣王，都朝歌。</p><p>文有太师闻仲，武有镇国武成王黄飞虎；文足以安邦，武足以定国。中宫元配皇后姜氏，西宫妃黄氏，馨庆宫妃杨氏；三宫后妃，皆德性贞静，柔和贤淑。纣王坐享大平，万民乐业，风调雨顺，国泰民安；四夷拱手，八方宾服，八百镇诸侯尽朝于商——有四路大诸侯率领八百小诸侯，东伯侯姜桓楚，居于东鲁，南伯侯鄂崇禹，西伯侯姬昌，北伯侯崇侯虎；每一镇诸侯领二百镇小诸侯，共八百镇诸侯属商。</p><p>纣王七年，春二月，忽报到朝歌，反了北海七十二路诸侯袁福通……太师闻仲奉敕征北。不题。</p><p>一日，纣王早朝登殿，设聚文武。但见：</p><p>瑞霭纷纭，金銮殿上坐君王；祥光缭绕，白玉阶前列文武。 沉檀喷金炉，则见那珠高卷；兰麝氤氲笼绛纱，且看他帘低垂。</p><p>正值天子朝退，百官俱散，纣王驾回寿仙宫。忽然一阵狂风，将殿角上吹下一幅尘埃来，落在纣王面前。纣王见有一卷文书，取而看之，乃女娲娘娘圣诞之辰，请纣王往女娲宫降香。纣王乃问当驾官曰：&quot;女娲娘娘有何功德，朕轻万乘而往降香？&quot;当驾官启奏曰：&quot;女娲娘娘乃上古神女，生有圣德。那时共工氏头触不周山，天倾西北，地陷东南；女娲乃采五色石，炼之以补青天，故有功于百姓。黎庶立禋祀以报之。今朝歌祀此福神，则四时康泰，国祚绵长，风调雨顺，灾害潜消。此福国庇民之正神，陛下当往行香。&quot;王曰：&quot;准卿奏章。&quot;纣王还宫，次日，命排銮舆，往女娲宫进香。</p><h2 id="作品评价" tabindex="-1">作品评价 <a class="header-anchor" href="#作品评价" aria-label="Permalink to &quot;作品评价&quot;">​</a></h2><p>《封神演义》依托商周交战的历史背景，用武王伐纣的框架，写了一部充满想象的神魔小说。小说中的许多故事和人物，如姜子牙封神、哪吒闹海、杨戬七十二变等，都已成为中国文化中家喻户晓的经典。该书对後世的戏曲、小说、民间信仰都产生了深远的影响。</p>',27)])])}const f=e(r,[["render",p]]);export{u as __pageData,f as default};
